import{_ as e,o as s,c as n,a0 as i}from"./chunks/framework.CI7OaYtj.js";const u=JSON.parse('{"title":"多语言篇","description":"","frontmatter":{},"headers":[],"relativePath":"guide/i18n.md","filePath":"guide/i18n.md"}'),t={name:"guide/i18n.md"};function l(o,a,p,c,r,d){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="多语言篇" tabindex="-1">多语言篇 <a class="header-anchor" href="#多语言篇" aria-label="Permalink to &quot;多语言篇&quot;">​</a></h1><p>国际化基于 <code>lime-i18n</code>，语言包位于 <code>src/i18n/locales/</code>，默认提供简体中文与英语。</p><h2 id="添加文案" tabindex="-1">添加文案 <a class="header-anchor" href="#添加文案" aria-label="Permalink to &quot;添加文案&quot;">​</a></h2><p>同时修改：</p><ul><li><code>src/i18n/locales/zh-CN.json</code></li><li><code>src/i18n/locales/en-US.json</code></li></ul><p>只加一边会导致切换语言时直接显示 key。</p><h2 id="页面使用" tabindex="-1">页面使用 <a class="header-anchor" href="#页面使用" aria-label="Permalink to &quot;页面使用&quot;">​</a></h2><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { $t, getI18nText, setNavigationBarTitle } from &#39;@/src/i18n/utils/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const title = $t(&#39;basic.langTitle&#39;);</span></span>
<span class="line"><span>const label = getI18nText(&#39;basic.langPreview&#39;);</span></span>
<span class="line"><span>setNavigationBarTitle(&#39;basic.langTitle&#39;);</span></span></code></pre></div><ul><li><code>$t()</code>：明确知道是 key 时使用。</li><li><code>getI18nText()</code>：值可能是 key，也可能是中文原文时使用。</li><li><code>setNavigationBarTitle()</code>：传 key，内部负责翻译并同步自定义导航栏。</li></ul><h2 id="切换语言" tabindex="-1">切换语言 <a class="header-anchor" href="#切换语言" aria-label="Permalink to &quot;切换语言&quot;">​</a></h2><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { useI18nStore } from &#39;@/src/store/index.uts&#39;;</span></span>
<span class="line"><span>import { setTabbarItem } from &#39;@/src/tabbar/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const i18nStore = useI18nStore();</span></span>
<span class="line"><span>i18nStore.setLocale(&#39;en-US&#39;);</span></span>
<span class="line"><span>setTabbarItem();</span></span></code></pre></div><p>语言会自动持久化。自定义 TabBar 文案不是响应式的，切换后需要主动刷新。</p><h2 id="默认语言" tabindex="-1">默认语言 <a class="header-anchor" href="#默认语言" aria-label="Permalink to &quot;默认语言&quot;">​</a></h2><p>在 <code>.env</code> 中设置：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VITE_DEFAULT_LOCALE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=zh-CN</span></span></code></pre></div><blockquote><p>完整 key 规则、初始语言优先级和 API 说明见 <a href="https://github.com/cq112233/unibestX/blob/main/src/i18n/README.md" target="_blank" rel="noreferrer">src/i18n/README.md</a>。</p></blockquote>`,16)])])}const b=e(t,[["render",l]]);export{u as __pageData,b as default};
